solution_code:
class TodoList {
    constructor() {
        this.todos = [];
    }
    add(task) {
        this.todos.push({ task, done: false });
    }
    complete(index) {
        if (index >= 0 && index < this.todos.length) {
            this.todos[index].done = true;
        }
    }
    getPending() {
        return this.todos.filter(t => !t.done).map(t => t.task);
    }
}
